def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==2 and (r,c) not in seen:
          q=[(r,c)];seen.add((r,c)); comp=[]
          while q:
            x,y=q.pop();comp.append((x,y))
            for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
              if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
          comps.append(comp)
    out=[row[:] for row in grid]
    # Three-cell T motifs point toward the singleton that completes the corresponding 3x3 plus pattern.
    for comp in comps:
      if len(comp)==3:
        rs=[x for x,y in comp];cs=[y for x,y in comp]
        if len(set(rs))==1:
          r=rs[0]; c=min(cs)
          if max(cs)-c==2 and r>0: out[r-1][c+1]=2
        elif len(set(cs))==1:
          c=cs[0]; r=min(rs)
          if max(rs)-r==2 and c>0: out[r+1][c-1]=2
    return out
