def transform(grid):
    # Gather each connected T tetromino and its orientation. Each has one
    # central junction and three arms, identified by missing cardinal arm.
    h,w=len(grid),len(grid[0]); seen=set(); dirs=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop();comp.append((x,y))
          for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
              seen.add((a,b));q.append((a,b))
        if len(comp)!=4: continue
        S=set(comp); center=next(((x,y) for x,y in S if sum((x+dx,y+dy) in S for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)))==3),None)
        if center is None: continue
        x,y=center
        if (x-1,y) not in S: dirs.append('U')
        elif (x+1,y) not in S: dirs.append('D')
        elif (x,y-1) not in S: dirs.append('L')
        else: dirs.append('R')
    # To be validated against additional examples; observed target output has
    # three top/bottom and three left/right motif indicators.
    out=[[0]*6 for _ in range(3)]
    for i,d in enumerate(dirs[:6]):
      r=0 if d in ('U','D') else 2
      c=(i%3)*2
      out[r][c]=3 if d in ('U','L') else 1
      out[r][c+1]=0
    return out

