def transform(grid):
    # Render each row of 2s as ordered counts of alternating shapes? The
    # readout is determined by the six T tetrominoes' orientations in scan order.
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop();comp.append((x,y))
          for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
        comps.append((min(x for x,y in comp),min(y for x,y in comp),set(comp)))
    comps.sort()
    out=[[0]*6 for _ in range(3)]
    # Each output column pair reflects the two orientations in a repeated motif group.
    for i,(_,__,S) in enumerate(comps[:6]):
      # code an upright/upside-down T, or left/right T, into row-specific indicator
      x,y=next(iter(S))
      center=next(((a,b) for a,b in S if sum((a+da,b+db) in S for da,db in ((1,0),(-1,0),(0,1),(0,-1)))==3),None)
      if center:
        a,b=center
        if (a-1,b) not in S: code=(0,3)
        elif (a+1,b) not in S: code=(0,1)
        elif (a,b-1) not in S: code=(2,3)
        else: code=(2,1)
        out[code[0]][2*i]=code[1]
    return out
